import Link from "next/link";
import type { ReactNode } from "react";
import type { ShortlistContact } from "@/lib/shortlist";
import { DeleteButton } from "@/components/forms";
import { ContactShortlistAction } from "./ContactShortlistAction";
import styles from "./contacts.module.css";

export type ContactListItem = ShortlistContact & {
  shortlistRemovedAt: Date | null;
};

export function ContactRow({
  contact: c,
  expandControl,
}: {
  contact: ContactListItem;
  expandControl?: ReactNode;
}) {
  return (
    <li
      className={`${styles.contactRow} workspace-mono:grid workspace-mono:grid-cols-[40px_minmax(0,1fr)_auto] workspace-mono:gap-x-3.5 workspace-mono:gap-y-2 workspace-mono:p-4 workspace-mono:rounded-[12px] workspace-mono:shadow-none workspace-mono:transform-none workspace-mono:[@media(max-width:479px)]:p-3.5 workspace-mono:[@media(max-width:479px)]:gap-x-2.5 hover-card flex flex-wrap items-center gap-3.5 rounded-[var(--appearance-radius,18px)] border border-[var(--contacts-border)] bg-[var(--contacts-surface)] px-[18px] py-3.5 hover:border-[var(--contacts-strong)]`}
    >
      <span
        aria-hidden="true"
        className={`workspace-mono:col-start-1 workspace-mono:row-start-1 workspace-mono:row-span-2 workspace-mono:self-start workspace-mono:size-10 workspace-mono:text-[15px] grid size-[42px] shrink-0 place-items-center rounded-full bg-[image:var(--contacts-gradient)] font-extrabold text-[var(--appearance-on-primary,var(--color-contactrow-detail-1))]`}
      >
        {c.name.trim().charAt(0).toUpperCase() ||
          c.email.charAt(0).toUpperCase()}
      </span>
      <div
        className={`workspace-mono:col-start-2 workspace-mono:row-start-1 workspace-mono:self-center min-w-0 flex-1 basis-36`}
      >
        <p className="truncate font-bold" title={c.name}>
          {c.name}
        </p>
        <p
          className="workspace-mono:text-[12px] workspace-mono:leading-[1.6] truncate text-[13.5px] text-[var(--contacts-muted)]"
          title={`${c.email}${c.company ? ` · ${c.company}` : ""}`}
        >
          {c.email}
          {c.company && (
            <>
              {" "}
              ·{" "}
              <span className={`${styles.roleBadge} ${styles.company}`}>
                {c.company}
              </span>
            </>
          )}
        </p>
      </div>
      <span
        className={`${styles.roleBadge} workspace-mono:col-start-2 workspace-mono:row-start-2 workspace-mono:justify-self-start workspace-mono:self-center workspace-mono:py-1 workspace-mono:px-[9px] workspace-mono:text-[11px] workspace-mono:leading-[1.5] workspace-mono:[@media(max-width:1099px)]:col-[2/-1] max-w-full rounded-full bg-[var(--appearance-wash,var(--color-contactrow-detail-2))] px-3 py-1 text-[12.5px] font-semibold break-words`}
      >
        {c.jobRole || "Choose a job role"}
      </span>
      {expandControl && (
        <div
          className={`${styles.expandControl} workspace-mono:block workspace-mono:col-start-3 workspace-mono:row-start-1 workspace-mono:justify-self-end contents`}
        >
          {expandControl}
        </div>
      )}
      <div
        className={`${styles.actions} workspace-mono:col-start-3 workspace-mono:row-start-2 workspace-mono:w-auto workspace-mono:gap-1.5 workspace-mono:self-center workspace-mono:[@media(max-width:1099px)]:col-[2/-1] workspace-mono:[@media(max-width:1099px)]:row-start-3 workspace-mono:[@media(max-width:1099px)]:mt-1 workspace-mono:[@media(max-width:1099px)]:justify-self-end flex w-full flex-wrap items-center justify-end gap-1`}
      >
        <ContactShortlistAction
          previouslySent={c.previouslySent}
          iconOnly
          contactId={c.id}
          inShortlist={
            !c.shortlistRemovedAt &&
            (c.blocked || !c.previouslySent || c.followUp)
          }
          blocked={c.blocked}
          active={true}
        />
        <Link
          href={`/contacts?edit=${c.id}`}
          className={`${styles.secondary} secondary-button button-interaction inline-flex items-center justify-center min-h-11 py-2 px-4 [border:1px_solid_var(--contacts-strong)] rounded-full text-[13px] font-semibold text-[var(--contacts-purple)]`}
        >
          Edit
        </Link>
        <DeleteButton id={c.id} kind="contact" />
      </div>
    </li>
  );
}
